INSERT OR REPLACE INTO "char_abilities" VALUES(1330001000,3,2014101,'(系列条件)支援攻击／支援反击 LV1','[{"tid":201410101,"trait_id":201410101,"trait":{"id":201410101,"trait_type":51,"trait_value":1,"desc":"搭乘单位含有「机动战士高达SEED DESTINY」系列时，\n「支援攻击／反击」+1次","action_timing":0,"tlimit":0,"active_condition_set_id":1000250,"target_condition_set_id":1000001,"value_source_condition_set_id":0,"target_weapon_condition_id":0,"use_battle_animation":false,"battle_power_value_rate_percent":5,"trait_boost_condition_set_id":0,"active_condition":{"id":1000250,"trait_condition_set_id":1000250,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"3300","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold":0,"en_rate_gte_threshold":0,"en_value_lte_threshold":0,"en_value_gte_threshold":0,"use_hp_rate_lte_threshold":false,"attack_distance_gte_threshold":0,"attack_distance_lte_threshold":0,"turn_number":0,"is_in_chance_step":false,"is_in_one_on_one":false,"unit_ids":"","character_ids":"","character_tags_id":"","character_series_id":"","tags":null,"series":{"id":3300,"world_id":0,"name":"机动战士高达SEED DESTINY","desc":"宇宙纪元70年。\n「血腥情人节」这场悲剧，导致札多与地球联合的战争浮上台面并白热化，双方付出惨烈牺牲，直到第二次扬京‧杜埃攻防战后才缔结停战条约。\n但并不代表世界就此和平……\n隶属地球联合军的欧普遭侵略时，真‧飞鸟被卷入其中，亲眼看著双亲与妹妹丧生。\n遭逢打击的他离开奥布，前往P.L.A.N.T.领土……\n宇宙纪元73年。\n真成为札多的战士，驾驶高达投入战场……","icon":"series_3300","sort":710,"schedule_id":0,"scenario_stage_series_id":3300,"scenario":null,"scenarios":null,"scenario_stages":null},"character_series":null,"character_tags":null},"target_condition":{"id":1000001,"trait_condition_set_id":1000001,"group_id":"","target":"Owner","unit_tags":"","unit_role":"","unit_series":"","unit_size":"","tension":"","standby_terrain":"","weapon_attribute":"","weapon_attack_attribute":"","map_battle_action":"","hp_type":0,"hp_rate_lte_threshold":0,"hp_rate_gte_threshold":0,"en_rate_lte_threshold"